const loadedHomeModuleScripts = {};

const MisThaiDate = (() => {
  const monthNames = ['มกราคม', 'กุมภาพันธ์', 'มีนาคม', 'เมษายน', 'พฤษภาคม', 'มิถุนายน', 'กรกฎาคม', 'สิงหาคม', 'กันยายน', 'ตุลาคม', 'พฤศจิกายน', 'ธันวาคม'];
  const monthAliases = [
    ['มกราคม', 'ม.ค.'],
    ['กุมภาพันธ์', 'ก.พ.'],
    ['มีนาคม', 'มี.ค.'],
    ['เมษายน', 'เม.ย.'],
    ['พฤษภาคม', 'พ.ค.'],
    ['มิถุนายน', 'มิ.ย.'],
    ['กรกฎาคม', 'ก.ค.'],
    ['สิงหาคม', 'ส.ค.'],
    ['กันยายน', 'ก.ย.'],
    ['ตุลาคม', 'ต.ค.'],
    ['พฤศจิกายน', 'พ.ย.'],
    ['ธันวาคม', 'ธ.ค.']
  ];

  function monthNumber(value) {
    const text = String(value || '').trim();
    const foundIndex = monthAliases.findIndex((aliases) => aliases.includes(text));
    return foundIndex >= 0 ? foundIndex + 1 : 0;
  }

  function parse(value) {
    const raw = String(value || '').trim();
    if (!raw) return null;

    let match = raw.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
    if (match) {
      let year = Number(match[1]);
      if (year > 2400) year -= 543;
      return { day: Number(match[3]), month: Number(match[2]), yearCe: year };
    }

    match = raw.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})$/);
    if (match) {
      let year = Number(match[3]);
      if (year > 2400) year -= 543;
      return { day: Number(match[1]), month: Number(match[2]), yearCe: year };
    }

    match = raw.match(/^(\d{1,2})\s+([^\d\s]+)\s+(?:พ\.ศ\.|ค\.ศ\.)?\s*(\d{4})$/);
    if (match) {
      const month = monthNumber(match[2]);
      let year = Number(match[3]);
      if (year > 2400) year -= 543;
      return month ? { day: Number(match[1]), month, yearCe: year } : null;
    }

    return null;
  }

  function formatInput(value) {
    const parsed = parse(value);
    if (!parsed) return '';
    return `${String(parsed.day).padStart(2, '0')}/${String(parsed.month).padStart(2, '0')}/${parsed.yearCe + 543}`;
  }

  function formatDisplay(value) {
    const parsed = parse(value);
    if (!parsed) return String(value || '').trim();
    return `${parsed.day} ${monthNames[parsed.month - 1]} พ.ศ. ${parsed.yearCe + 543}`;
  }

  function toIsoCe(value) {
    const parsed = parse(value);
    if (!parsed) return '';
    return `${parsed.yearCe}-${String(parsed.month).padStart(2, '0')}-${String(parsed.day).padStart(2, '0')}`;
  }

  function getState(input) {
    const now = new Date();
    const parsed = parse(input && input.value) || {
      day: now.getDate(),
      month: now.getMonth() + 1,
      yearCe: now.getFullYear()
    };
    return {
      monthIndex: parsed.month - 1,
      yearCe: parsed.yearCe,
      selectedDay: parsed.day
    };
  }

  function render(control, state) {
    const picker = control.querySelector('[data-thai-date-picker]');
    if (!picker) return;
    const firstDay = new Date(state.yearCe, state.monthIndex, 1).getDay();
    const daysInMonth = new Date(state.yearCe, state.monthIndex + 1, 0).getDate();
    const cells = [];
    for (let i = 0; i < firstDay; i += 1) cells.push('<span class="thai-date-empty"></span>');
    for (let day = 1; day <= daysInMonth; day += 1) {
      const active = day === state.selectedDay ? ' active' : '';
      cells.push(`<button type="button" class="thai-date-day${active}" data-thai-date-day="${day}">${day}</button>`);
    }

    picker.innerHTML = `
      <div class="thai-date-head">
        <button type="button" data-thai-date-prev aria-label="เดือนก่อนหน้า">‹</button>
        <div class="thai-date-selectors">
          <select aria-label="เลือกเดือน" data-thai-date-month>
            ${monthNames.map((name, index) => `<option value="${index}"${index === state.monthIndex ? ' selected' : ''}>${name}</option>`).join('')}
          </select>
          <select aria-label="เลือกปี พ.ศ." data-thai-date-year>
            ${Array.from({ length: 121 }, (_, index) => {
              const yearBe = new Date().getFullYear() + 543 + 20 - index;
              return `<option value="${yearBe - 543}"${yearBe - 543 === state.yearCe ? ' selected' : ''}>${yearBe}</option>`;
            }).join('')}
          </select>
        </div>
        <button type="button" data-thai-date-next aria-label="เดือนถัดไป">›</button>
      </div>
      <div class="thai-date-weekdays"><span>อา</span><span>จ</span><span>อ</span><span>พ</span><span>พฤ</span><span>ศ</span><span>ส</span></div>
      <div class="thai-date-grid">${cells.join('')}</div>
      <div class="thai-date-actions"><button type="button" data-thai-date-today>วันนี้</button></div>
    `;
  }

  function open(control) {
    if (!control) return;
    let picker = control.querySelector('[data-thai-date-picker]');
    if (!picker) {
      picker = document.createElement('div');
      picker.className = 'thai-date-picker';
      picker.dataset.thaiDatePicker = '';
      control.appendChild(picker);
    }
    const state = getState(control.querySelector('[data-thai-date-input]'));
    control._thaiDateState = state;
    render(control, state);
    picker.hidden = false;
  }

  function closeAll(exceptControl) {
    document.querySelectorAll('[data-thai-date-control]').forEach((control) => {
      if (control === exceptControl) return;
      const picker = control.querySelector('[data-thai-date-picker]');
      if (picker) picker.hidden = true;
    });
  }

  function setInputValue(control, state) {
    const input = control.querySelector('[data-thai-date-input]');
    if (!input) return;
    input.value = `${String(state.selectedDay).padStart(2, '0')}/${String(state.monthIndex + 1).padStart(2, '0')}/${state.yearCe + 543}`;
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
  }

  function init(root = document) {
    root.querySelectorAll('[data-thai-date-control]').forEach((control) => {
      if (control.dataset.thaiDateReady === 'true') return;
      control.dataset.thaiDateReady = 'true';
      const input = control.querySelector('[data-thai-date-input]');
      control.querySelector('[data-thai-date-toggle]')?.addEventListener('click', () => {
        const picker = control.querySelector('[data-thai-date-picker]');
        closeAll(control);
        if (picker && !picker.hidden) picker.hidden = true;
        else open(control);
      });
      input?.addEventListener('blur', () => {
        const formatted = formatInput(input.value);
        if (formatted) input.value = formatted;
      });
    });
  }

  document.addEventListener('click', (event) => {
    if (!event.target.closest('[data-thai-date-control]')) closeAll();
  });

  document.addEventListener('click', (event) => {
    const control = event.target.closest('[data-thai-date-control]');
    if (!control) return;
    const state = control._thaiDateState || getState(control.querySelector('[data-thai-date-input]'));

    if (event.target.closest('[data-thai-date-prev]')) {
      state.monthIndex -= 1;
      if (state.monthIndex < 0) {
        state.monthIndex = 11;
        state.yearCe -= 1;
      }
      control._thaiDateState = state;
      render(control, state);
      return;
    }

    if (event.target.closest('[data-thai-date-next]')) {
      state.monthIndex += 1;
      if (state.monthIndex > 11) {
        state.monthIndex = 0;
        state.yearCe += 1;
      }
      control._thaiDateState = state;
      render(control, state);
      return;
    }

    if (event.target.closest('[data-thai-date-today]')) {
      const today = new Date();
      state.selectedDay = today.getDate();
      state.monthIndex = today.getMonth();
      state.yearCe = today.getFullYear();
      control._thaiDateState = state;
      setInputValue(control, state);
      render(control, state);
      const picker = control.querySelector('[data-thai-date-picker]');
      if (picker) picker.hidden = true;
      return;
    }

    const dayButton = event.target.closest('[data-thai-date-day]');
    if (!dayButton) return;
    state.selectedDay = Number(dayButton.dataset.thaiDateDay);
    control._thaiDateState = state;
    setInputValue(control, state);
    const picker = control.querySelector('[data-thai-date-picker]');
    if (picker) picker.hidden = true;
  });

  document.addEventListener('change', (event) => {
    const control = event.target.closest('[data-thai-date-control]');
    if (!control) return;
    const state = control._thaiDateState || getState(control.querySelector('[data-thai-date-input]'));
    if (event.target.matches('[data-thai-date-month]')) {
      state.monthIndex = Number(event.target.value);
      control._thaiDateState = state;
      render(control, state);
    }
    if (event.target.matches('[data-thai-date-year]')) {
      state.yearCe = Number(event.target.value);
      control._thaiDateState = state;
      render(control, state);
    }
  });

  return { parse, formatInput, formatDisplay, toIsoCe, init };
})();

window.MisThaiDate = MisThaiDate;

const Auth = {
  getToken() {
    return localStorage.getItem(STORAGE.TOKEN) || '';
  },
  setToken(token) {
    localStorage.setItem(STORAGE.TOKEN, token || '');
  },
  getUser() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE.USER) || 'null');
    } catch (_) {
      return null;
    }
  },
  setUser(user) {
    localStorage.setItem(STORAGE.USER, JSON.stringify(user || null));
  },
  clear() {
    localStorage.removeItem(STORAGE.TOKEN);
    localStorage.removeItem(STORAGE.USER);
  },
  getExpiresAt() {
    const user = this.getUser();
    const expiresAt = Number(user && user.expiresAt);
    return Number.isFinite(expiresAt) ? expiresAt : 0;
  },
  isExpired() {
    const expiresAt = this.getExpiresAt();
    return Boolean(expiresAt && Date.now() >= expiresAt);
  },
  isLoggedIn() {
    if (!this.getToken() || !this.getUser()) return false;
    if (this.isExpired()) {
      this.clear();
      return false;
    }
    return true;
  }
};

function isHrmAdminUser(user) {
  return String(user && (user.hrRole || user.HR_ROLE) || '').trim().toUpperCase() === 'ADMIN';
}

function isMisAdminUser(user) {
  return String(user && (user.role || user.MIS_ROLE) || '').trim().toUpperCase() === 'ADMIN';
}

function normalizeApiResult(result) {
  const ok = result && (result.ok === true || result.success === true);
  const user = result && (result.user || result.data || result.account || null);
  const token = result && (
    result.token ||
    result.sessionToken ||
    result.session_token ||
    (result.user && result.user.token) ||
    (result.data && result.data.token) ||
    ''
  );

  return {
    raw: result || {},
    ok,
    message: result && result.message || '',
    needsInitialPassword: Boolean(result && (
      result.needsInitialPassword ||
      result.needInitialPassword ||
      result.requireInitialPassword ||
      result.passwordRequired
    )),
    user,
    token
  };
}

function normalizeUser(user, token) {
  user = user || {};
  const sessionStartedAt = Number(user.sessionStartedAt) || Date.now();
  const expiresAt = Number(user.expiresAt) || sessionStartedAt + MIS_CONFIG.SESSION_TTL_MS;
  return {
    token: token || user.token || '',
    personId: user.PERSON_ID || user.personId || user.person_id || '',
    fullName: user.FULL_NAME || user.fullName || user.name || '',
    email: user.EMAIL || user.email || '',
    phone: user.PHONE || user.phone || '',
    role: user.MIS_ROLE || user.role || '',
    hrRole: user.HR_ROLE || user.hrRole || '',
    active: user.MIS_ACTIVE ?? user.active ?? '',
    system: user.MIS || user.system || MIS_CONFIG.SYSTEM,
    sessionStartedAt,
    expiresAt
  };
}

function redirectToLogin() {
  Auth.clear();
  window.location.href = 'login.html';
}

function handleExpiredSession(message) {
  Auth.clear();
  window.location.href = `login.html?expired=1&message=${encodeURIComponent(message || 'Session หมดอายุ กรุณาเข้าสู่ระบบใหม่')}`;
}

function isExpiredSessionMessage(message) {
  return /session\s*หมดอายุ|session expired|token.*หมดอายุ|กรุณาเข้าสู่ระบบใหม่/i.test(String(message || ''));
}

function scheduleSessionExpiry(logoutNow) {
  const expiresAt = Auth.getExpiresAt();
  if (!expiresAt) return;

  const delay = expiresAt - Date.now();
  if (delay <= 0) {
    logoutNow();
    return;
  }

  window.setTimeout(logoutNow, Math.min(delay, 2147483647));
}

function formatCountdown(ms) {
  const totalSeconds = Math.max(0, Math.ceil(ms / 1000));
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  return [hours, minutes, seconds].map(value => String(value).padStart(2, '0')).join(':');
}

function startSessionCountdown(onExpired) {
  const wrapper = document.getElementById('session-countdown');
  const valueEl = document.getElementById('session-countdown-value');
  const expiresAt = Auth.getExpiresAt();
  if (!wrapper || !valueEl || !expiresAt) return null;

  const update = () => {
    const remaining = expiresAt - Date.now();
    valueEl.textContent = formatCountdown(remaining);
    wrapper.classList.toggle('warning', remaining <= 10 * 60 * 1000 && remaining > 60 * 1000);
    wrapper.classList.toggle('danger', remaining <= 60 * 1000);
    wrapper.title = remaining > 0
      ? `Session จะหมดอายุใน ${formatCountdown(remaining)}`
      : 'Session หมดอายุแล้ว';

    if (remaining <= 0) {
      window.clearInterval(timerId);
      onExpired();
    }
  };

  update();
  const timerId = window.setInterval(update, 1000);
  return timerId;
}

async function verifyStoredSession() {
  if (!Auth.isLoggedIn()) return null;

  const result = await api('getSession');
  if (!result.ok) {
    const stored = Auth.getUser() || {};
    const message = String(result.message || '').toLowerCase();
    if (message.includes('invalid action') && !Auth.isExpired() && Auth.getToken()) {
      return stored;
    }

    Auth.clear();
    return null;
  }

  const stored = Auth.getUser() || {};
  const verified = normalizeUser(result.user || stored, Auth.getToken());
  verified.sessionStartedAt = stored.sessionStartedAt || verified.sessionStartedAt;
  verified.expiresAt = stored.expiresAt || verified.expiresAt;
  Auth.setUser(verified);
  return verified;
}

async function api(action, payload = {}) {
  const url = new URL(MIS_CONFIG.API_URL);
  url.searchParams.set('action', action);
  url.searchParams.set('system', MIS_CONFIG.SYSTEM);

  const body = Object.assign({}, payload || {}, {
    action,
    system: MIS_CONFIG.SYSTEM
  });

  const token = Auth.getToken();
  if (token) body.token = token;

  let lastError = null;
  for (let attempt = 1; attempt <= 2; attempt += 1) {
    try {
      const response = await fetch(url.toString(), {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify(body)
      });

      const text = await response.text();
      try {
        return normalizeApiResult(JSON.parse(text));
      } catch (_) {
        const preview = String(text || '').trim().slice(0, 180);
        lastError = {
          ok: false,
          message: preview
            ? `Backend ไม่ได้ส่ง JSON กลับมา: ${preview}`
            : 'Backend ไม่ได้ส่ง JSON กลับมา กรุณาตรวจสอบ Apps Script deploy',
          raw: { text }
        };
      }
    } catch (err) {
      lastError = {
        ok: false,
        message: err && err.message ? err.message : 'เชื่อมต่อ API ไม่สำเร็จ',
        raw: { error: err }
      };
    }
    if (attempt < 2) await new Promise(resolve => setTimeout(resolve, 650));
  }
  return lastError || { ok: false, message: 'เชื่อมต่อ API ไม่สำเร็จ' };
}

function setAlert(id, message, type) {
  const el = document.getElementById(id);
  if (!el) return;
  el.textContent = message || '';
  el.className = `alert alert-${type || 'info'}${message ? ' show' : ''}`;
}

function setForgotResetSentAlert() {
  const el = document.getElementById('forgot-alert');
  if (!el) return;
  el.innerHTML = [
    '<div>ส่งลิงก์รีเซ็ตรหัสผ่านไปยังอีเมลแล้ว</div>',
    '<div class="alert-danger-note">หากยังไม่ได้รับอีเมล รบกวนเช็กที่จดหมายขยะ (Spam/Junk Mail)</div>'
  ].join('');
  el.className = 'alert alert-success show';
}

function setButtonLoading(button, isLoading, loadingText) {
  if (!button) return;
  if (!button.dataset.originalText) button.dataset.originalText = button.textContent;
  button.disabled = isLoading;
  button.classList.toggle('is-loading', Boolean(isLoading));
  button.setAttribute('aria-busy', String(Boolean(isLoading)));
  button.textContent = isLoading ? loadingText : button.dataset.originalText;
}

function getActiveMisUser() {
  if (typeof currentPersonalUser !== 'undefined' && currentPersonalUser) return currentPersonalUser;
  if (typeof Auth !== 'undefined' && Auth && typeof Auth.getUser === 'function') return Auth.getUser() || {};
  return {};
}

function buildHrmLaunchHref(baseHref) {
  const token = Auth.getToken();
  const user = Auth.getUser() || {};
  if (!token) return baseHref || 'HRM/hrm-admin.html';

  const hash = new URLSearchParams();
  hash.set('misToken', token);
  if (user.email) hash.set('misEmail', user.email);
  return `${baseHref || 'HRM/hrm-admin.html'}#${hash.toString()}`;
}

function showInitialPassword(email) {
  const setupCard = document.getElementById('setup-card');
  const setupEmail = document.getElementById('setup-email');
  if (setupEmail) setupEmail.value = email || '';
  if (setupCard) setupCard.classList.add('show');
}

function hideInitialPassword() {
  const setupCard = document.getElementById('setup-card');
  if (setupCard) setupCard.classList.remove('show');
}

function showCard(id) {
  ['setup-card', 'forgot-card', 'reset-card'].forEach(cardId => {
    const card = document.getElementById(cardId);
    if (card) card.classList.toggle('show', cardId === id);
  });
}

function getResetUrlBase() {
  const url = new URL(window.location.href);
  url.search = '';
  url.hash = '';
  return url.toString();
}

function getSafeNextPath(value) {
  const next = String(value || '').trim();
  if (!next || next.startsWith('//') || /^[a-z][a-z\d+.-]*:/i.test(next)) return '';
  return next.startsWith('/') ? next.slice(1) : next;
}

function getRecordValue(record, keys) {
  const normalized = record || {};
  for (const key of keys) {
    if (normalized[key] != null && String(normalized[key]).trim() !== '') return normalized[key];
  }
  return '';
}

function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, (char) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;'
  }[char]));
}

function normalizeRecord(record) {
  return Object.fromEntries(Object.entries(record || {}).map(([key, value]) => [String(key).trim(), value]));
}

function openModal(id) {
  document.getElementById(id)?.classList.remove('hidden');
}

function closeModal(id) {
  document.getElementById(id)?.classList.add('hidden');
}

function hasDisplayValue(value) {
  if (value === undefined || value === null) return false;
  return String(value).trim() !== '';
}

function displayValue(value, fallback = '-') {
  return hasDisplayValue(value) ? String(value).trim() : fallback;
}

function setInputValue(id, value) {
  const el = document.getElementById(id);
  if (el) el.value = value || '';
}

function refreshRequiredFieldLabels(root = document) {
  root.querySelectorAll('form .form-section label').forEach((label) => {
    const control = label.querySelector('input, select, textarea');
    const required = Boolean(control && control.required && !control.disabled && !control.readOnly);
    label.classList.toggle('required-field-label', required);
    if (!required) {
      label.querySelectorAll('.required-star').forEach((star) => star.remove());
      return;
    }

    const firstTextNode = Array.from(label.childNodes).find((node) => node.nodeType === Node.TEXT_NODE && node.textContent.trim());
    if (!firstTextNode) return;

    const next = firstTextNode.nextSibling;
    if (next && next.classList && next.classList.contains('required-star')) return;

    const star = document.createElement('span');
    star.className = 'required-star';
    star.textContent = '*';
    firstTextNode.after(star);
  });
}

function loadScriptOnce(src) {
  if (loadedHomeModuleScripts[src]) return loadedHomeModuleScripts[src];
  loadedHomeModuleScripts[src] = new Promise((resolve, reject) => {
    const existing = document.querySelector(`script[data-lazy-src="${src}"]`);
    if (existing) {
      existing.addEventListener('load', resolve, { once: true });
      existing.addEventListener('error', () => reject(new Error(`โหลด module ไม่สำเร็จ: ${src}`)), { once: true });
      return;
    }
    const script = document.createElement('script');
    script.src = src;
    script.async = false;
    script.dataset.lazySrc = src;
    script.onload = resolve;
    script.onerror = () => reject(new Error(`โหลด module ไม่สำเร็จ: ${src}`));
    document.body.appendChild(script);
  });
  return loadedHomeModuleScripts[src];
}

async function ensureHomeModule(viewName) {
  const moduleInfo = HOME_MODULES[viewName];
  if (!moduleInfo) return;
  await loadScriptOnce(moduleInfo.src);
  if (!moduleInfo.initialized && typeof window[moduleInfo.init] === 'function') {
    window[moduleInfo.init]();
    moduleInfo.initialized = true;
    refreshRequiredFieldLabels();
  }
}

function setChangePasswordAlert(message, type = 'info') {
  const el = document.getElementById('change-password-alert');
  if (!el) return;
  el.textContent = message || '';
  el.className = `data-alert data-alert-${type}`;
  el.hidden = !message;
}

function openChangePasswordModal() {
  const form = document.getElementById('change-password-form');
  form?.reset();
  setChangePasswordAlert('', 'info');
  openModal('change-password-modal');
  window.setTimeout(() => document.getElementById('current-password')?.focus(), 0);
}

async function submitChangePassword(event) {
  event.preventDefault();
  const form = document.getElementById('change-password-form');
  const button = document.getElementById('change-password-save-btn');
  if (!form) return;

  const currentPassword = document.getElementById('current-password')?.value || '';
  const newPassword = document.getElementById('new-password')?.value || '';
  const confirmPassword = document.getElementById('confirm-new-password')?.value || '';

  if (!currentPassword || !newPassword || !confirmPassword) {
    setChangePasswordAlert('กรุณากรอกรหัสผ่านให้ครบถ้วน', 'error');
    return;
  }
  if (newPassword.length < 6) {
    setChangePasswordAlert('รหัสผ่านใหม่ต้องมีอย่างน้อย 6 ตัวอักษร', 'error');
    return;
  }
  if (newPassword !== confirmPassword) {
    setChangePasswordAlert('รหัสผ่านใหม่และยืนยันรหัสผ่านไม่ตรงกัน', 'error');
    return;
  }

  setButtonLoading(button, true, 'กำลังบันทึก...');
  setChangePasswordAlert('กำลังเปลี่ยนรหัสผ่าน...', 'info');

  try {
    const result = await api('changePassword', { currentPassword, newPassword });
    if (!result.ok) {
      setChangePasswordAlert(result.message || 'เปลี่ยนรหัสผ่านไม่สำเร็จ', 'error');
      return;
    }
    form.reset();
    setChangePasswordAlert(result.message || 'เปลี่ยนรหัสผ่านสำเร็จ', 'info');
    window.setTimeout(() => closeModal('change-password-modal'), 900);
  } catch (err) {
    console.error(err);
    setChangePasswordAlert('เชื่อมต่อ backend ไม่สำเร็จ: ' + err.message, 'error');
  } finally {
    setButtonLoading(button, false);
  }
}

function initLoginPage() {
  const loginForm = document.getElementById('login-form');
  const setupForm = document.getElementById('setup-form');
  const forgotForm = document.getElementById('forgot-form');
  const resetForm = document.getElementById('reset-form');
  const togglePassword = document.getElementById('toggle-password');
  const passwordInput = document.getElementById('password');
  const firstUseBtn = document.getElementById('first-use-btn');
  const forgotPasswordBtn = document.getElementById('forgot-password-btn');
  const params = new URLSearchParams(window.location.search);
  const resetToken = params.get('resetToken') || '';
  const sessionExpired = params.get('expired') === '1';
  const sessionMessage = params.get('message') || '';
  const nextPath = getSafeNextPath(params.get('next'));

  if (resetToken) {
    Auth.clear();
  } else if (Auth.isLoggedIn()) {
    window.location.href = nextPath || 'index.html';
    return;
  }

  if (resetToken) {
    showCard('reset-card');
    setAlert('login-alert', 'กรุณาตั้งรหัสผ่านใหม่จากลิงก์ในอีเมล', 'info');
    document.getElementById('reset-password').focus();
  }

  if (sessionExpired) {
    setAlert('login-alert', sessionMessage || 'Session หมดอายุ กรุณาเข้าสู่ระบบใหม่', 'info');
    window.history.replaceState({}, document.title, getResetUrlBase());
  }

  togglePassword?.addEventListener('click', () => {
    const icon = document.getElementById('password-eye-icon');
    passwordInput.type = passwordInput.type === 'password' ? 'text' : 'password';
    if (icon) {
      icon.innerHTML = passwordInput.type === 'password'
        ? '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/>'
        : '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l3.59 3.59m0 0A9.953 9.953 0 0112 5c4.478 0 8.268 2.943 9.543 7a10.025 10.025 0 01-4.132 5.411m0 0L21 21"/>';
    }
  });

  firstUseBtn?.addEventListener('click', () => {
    const email = document.getElementById('email').value.trim();

    document.getElementById('password').value = '';
    showCard('setup-card');
    showInitialPassword(email);
    setAlert('login-alert', 'กรุณากรอกข้อมูลสำหรับเข้าใช้งานครั้งแรก', 'info');
    setAlert('setup-alert', '', 'info');
    document.getElementById(email ? 'setup-phone' : 'setup-email').focus();
  });

  forgotPasswordBtn?.addEventListener('click', () => {
    const email = document.getElementById('email').value.trim();
    document.getElementById('forgot-email').value = email;
    showCard('forgot-card');
    setAlert('login-alert', 'กรอกอีเมลเพื่อรับลิงก์รีเซ็ตรหัสผ่าน', 'info');
    setAlert('forgot-alert', '', 'info');
    document.getElementById('forgot-email').focus();
  });

  loginForm?.addEventListener('submit', async (event) => {
    event.preventDefault();

    const email = document.getElementById('email').value.trim();
    const password = document.getElementById('password').value;
    const button = document.getElementById('login-btn');

    setAlert('login-alert', 'กำลังตรวจสอบ...', 'success');
    hideInitialPassword();
    showCard('');
    setButtonLoading(button, true, 'กำลังตรวจสอบ...');

    try {
      const result = await api('login', { email, password });

      if (!result.ok) {
        if (result.needsInitialPassword) {
          setAlert('login-alert', result.message || 'กรุณาตั้งรหัสผ่านใหม่ก่อนเข้าใช้งาน', 'info');
          showCard('setup-card');
          showInitialPassword(email);
        } else {
          setAlert('login-alert', result.message || 'เข้าสู่ระบบไม่สำเร็จ', 'error');
        }
        return;
      }

      const user = normalizeUser(result.user, result.token);
      const token = result.token || user.token;
      if (!token) {
        setAlert('login-alert', 'เข้าสู่ระบบสำเร็จแต่ไม่พบ session token จาก backend', 'error');
        return;
      }

      user.token = token;
      user.sessionStartedAt = Date.now();
      user.expiresAt = user.sessionStartedAt + MIS_CONFIG.SESSION_TTL_MS;
      Auth.setToken(token);
      Auth.setUser(user);
      window.location.href = nextPath || 'index.html';
    } catch (err) {
      console.error(err);
      setAlert('login-alert', 'เชื่อมต่อ backend ไม่สำเร็จ: ' + err.message, 'error');
    } finally {
      setButtonLoading(button, false);
    }
  });

  setupForm?.addEventListener('submit', async (event) => {
    event.preventDefault();

    const email = document.getElementById('setup-email').value.trim();
    const phone = document.getElementById('setup-phone').value.trim();
    const password = document.getElementById('setup-password').value;
    const confirm = document.getElementById('setup-confirm').value;
    const button = document.getElementById('setup-btn');

    if (password.length < 6) {
      setAlert('setup-alert', 'รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร', 'error');
      return;
    }

    if (password !== confirm) {
      setAlert('setup-alert', 'รหัสผ่านและยืนยันรหัสผ่านไม่ตรงกัน', 'error');
      return;
    }

    setAlert('setup-alert', 'กำลังตั้งรหัสผ่าน...', 'success');
    setButtonLoading(button, true, 'กำลังบันทึก...');

    try {
      const result = await api('setInitialPassword', {
        email,
        phone,
        password,
        system: MIS_CONFIG.SYSTEM
      });

      if (!result.ok) {
        setAlert('setup-alert', result.message || 'ตั้งรหัสผ่านไม่สำเร็จ', 'error');
        return;
      }

      document.getElementById('password').value = '';
      setupForm.reset();
      hideInitialPassword();
      setAlert('login-alert', result.message || 'ตั้งรหัสผ่านสำเร็จ กรุณาเข้าสู่ระบบ', 'success');
      setAlert('setup-alert', '', 'info');
    } catch (err) {
      console.error(err);
      setAlert('setup-alert', 'เชื่อมต่อ backend ไม่สำเร็จ: ' + err.message, 'error');
    } finally {
      setButtonLoading(button, false);
    }
  });

  forgotForm?.addEventListener('submit', async (event) => {
    event.preventDefault();

    const email = document.getElementById('forgot-email').value.trim();
    const button = document.getElementById('forgot-submit-btn');

    if (!email) {
      setAlert('forgot-alert', 'กรุณากรอกอีเมล', 'error');
      return;
    }

    setAlert('forgot-alert', 'กำลังส่งอีเมลรีเซ็ต...', 'success');
    setButtonLoading(button, true, 'กำลังส่ง...');

    try {
      const result = await api('requestPasswordReset', {
        email,
        resetUrlBase: getResetUrlBase()
      });

      if (!result.ok) {
        setAlert('forgot-alert', result.message || 'ส่งอีเมลรีเซ็ตไม่สำเร็จ', 'error');
        return;
      }

      setForgotResetSentAlert();
    } catch (err) {
      console.error(err);
      setAlert('forgot-alert', 'เชื่อมต่อ backend ไม่สำเร็จ: ' + err.message, 'error');
    } finally {
      setButtonLoading(button, false);
    }
  });

  resetForm?.addEventListener('submit', async (event) => {
    event.preventDefault();

    const password = document.getElementById('reset-password').value;
    const confirm = document.getElementById('reset-confirm').value;
    const button = document.getElementById('reset-submit-btn');

    if (password.length < 6) {
      setAlert('reset-alert', 'รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร', 'error');
      return;
    }

    if (password !== confirm) {
      setAlert('reset-alert', 'รหัสผ่านและยืนยันรหัสผ่านไม่ตรงกัน', 'error');
      return;
    }

    setAlert('reset-alert', 'กำลังบันทึกรหัสผ่านใหม่...', 'success');
    setButtonLoading(button, true, 'กำลังบันทึก...');

    try {
      const result = await api('resetPasswordWithToken', {
        resetToken,
        password
      });

      if (!result.ok) {
        setAlert('reset-alert', result.message || 'รีเซ็ตรหัสผ่านไม่สำเร็จ', 'error');
        return;
      }

      setAlert('reset-alert', result.message || 'ตั้งรหัสผ่านใหม่สำเร็จ กรุณาเข้าสู่ระบบ', 'success');
      window.history.replaceState({}, document.title, getResetUrlBase());
      resetForm.reset();
    } catch (err) {
      console.error(err);
      setAlert('reset-alert', 'เชื่อมต่อ backend ไม่สำเร็จ: ' + err.message, 'error');
    } finally {
      setButtonLoading(button, false);
    }
  });
}

async function initHomePage() {
  if (!Auth.isLoggedIn()) {
    window.location.href = 'login.html';
    return;
  }

  let user;
  try {
    user = await verifyStoredSession();
  } catch (err) {
    console.error(err);
    redirectToLogin();
    return;
  }

  if (!user) {
    window.location.href = 'login.html';
    return;
  }
  if (!user.token || (!user.email && !user.personId)) {
    handleExpiredSession('Session ไม่สมบูรณ์ กรุณาเข้าสู่ระบบใหม่');
    return;
  }

  const isMisAdmin = isMisAdminUser(user);
  const isHrmAdmin = isHrmAdminUser(user);
  const roleLabels = {
    ADMIN: 'ผู้ดูแลระบบ',
    MANAGER: 'ผู้บริหาร',
    STAFF: 'เจ้าหน้าที่',
    USER: 'บุคลากร'
  };
  const fullName = user.fullName || '-';
  const role = roleLabels[String(user.role || '').toUpperCase()] || user.role || '-';
  const initial = fullName && fullName !== '-' ? fullName.trim().charAt(0) : '?';

  const setText = (id, value) => {
    const el = document.getElementById(id);
    if (el) el.textContent = value || '-';
  };

  setText('sidebar-user-initial', initial);
  setText('sidebar-user-name', fullName);
  setText('sidebar-user-email', user.email || '-');
  setText('sidebar-user-role', role);
  setText('account-name', fullName);
  setText('account-email', user.email || '-');
  setText('account-person-id', user.personId || '-');
  setText('account-role', role);

  document.querySelectorAll('[data-admin-only]').forEach((el) => {
    el.hidden = !isHrmAdmin;
    el.setAttribute('aria-hidden', String(!isHrmAdmin));
    if (!isHrmAdmin) el.setAttribute('tabindex', '-1');
    else el.removeAttribute('tabindex');
  });

  document.querySelectorAll('[data-mis-admin-only]').forEach((el) => {
    if (!isMisAdmin) {
      el.remove();
      return;
    }
    el.hidden = false;
    el.removeAttribute('aria-hidden');
    el.removeAttribute('tabindex');
    if (el.tagName === 'A') {
      el.href = buildHrmLaunchHref(el.getAttribute('href') || 'HRM/hrm-admin.html');
    }
  });

  let isLoggingOut = false;
  const setLogoutState = (isLoading) => {
    const topbarButton = document.getElementById('logout-btn');
    const sidebarButton = document.getElementById('sidebar-logout-btn');

    [topbarButton, sidebarButton].forEach((button) => {
      if (!button) return;
      button.disabled = isLoading;
      button.classList.toggle('is-loading', isLoading);
      button.setAttribute('aria-busy', String(isLoading));
    });

    if (topbarButton && isLoading) {
      topbarButton.dataset.originalHtml = topbarButton.dataset.originalHtml || topbarButton.innerHTML;
      topbarButton.innerHTML = '<span class="logout-spinner" aria-hidden="true"></span>';
      topbarButton.setAttribute('aria-label', 'กำลังออกจากระบบ');
      topbarButton.setAttribute('title', 'กำลังออกจากระบบ');
    }

    if (sidebarButton && isLoading) {
      sidebarButton.dataset.originalText = sidebarButton.dataset.originalText || sidebarButton.textContent;
      sidebarButton.textContent = 'กำลังออกจากระบบ...';
    }
  };

  const logout = async () => {
    if (isLoggingOut) return;
    isLoggingOut = true;
    setLogoutState(true);
    try {
      await api('logout');
    } catch (_) {
      // Logout locally even if backend is unavailable.
    }
    Auth.clear();
    window.location.href = 'login.html';
  };

  const expireSession = async () => {
    if (isLoggingOut) return;
    isLoggingOut = true;
    try {
      await api('logout');
    } catch (_) {
      // Expire locally even if backend is unavailable.
    }
    Auth.clear();
    window.location.href = 'login.html?expired=1';
  };

  scheduleSessionExpiry(expireSession);
  startSessionCountdown(expireSession);

  document.getElementById('logout-btn')?.addEventListener('click', logout);
  document.getElementById('sidebar-logout-btn')?.addEventListener('click', logout);
  document.getElementById('sidebar-user-card')?.addEventListener('click', openChangePasswordModal);
  document.getElementById('change-password-form')?.addEventListener('submit', submitChangePassword);
  if (typeof initPersonalModule === 'function') initPersonalModule();
  if (typeof initResearchModule === 'function') initResearchModule();
  if (typeof initFacultyPracticeModule === 'function') initFacultyPracticeModule();
  if (typeof initTrainingModule === 'function') initTrainingModule();
  refreshRequiredFieldLabels();
  document.querySelectorAll('[data-close-modal]').forEach((button) => {
    button.addEventListener('click', () => closeModal(button.dataset.closeModal));
  });

  document.querySelectorAll('.sidebar-section-toggle').forEach((button) => {
    button.addEventListener('click', () => {
      const expanded = button.getAttribute('aria-expanded') === 'true';
      button.setAttribute('aria-expanded', String(!expanded));
      button.classList.toggle('expanded', !expanded);
      button.nextElementSibling?.classList.toggle('show', !expanded);
    });
  });

  document.querySelectorAll('.sidebar-dashboard-title').forEach((button) => {
    button.addEventListener('click', () => {
      const expanded = button.getAttribute('aria-expanded') === 'true';
      button.setAttribute('aria-expanded', String(!expanded));
      button.classList.toggle('expanded', !expanded);
      button.nextElementSibling?.classList.toggle('show', !expanded);
    });
  });

  document.querySelectorAll('.sidebar-subsection-toggle').forEach((button) => {
    button.addEventListener('click', () => {
      const expanded = button.getAttribute('aria-expanded') === 'true';
      button.setAttribute('aria-expanded', String(!expanded));
      button.classList.toggle('expanded', !expanded);
      button.nextElementSibling?.classList.toggle('show', !expanded);
    });
  });

  let personalLoaded = false;
  let researchLoaded = false;
  let facultyPracticeLoaded = false;
  let trainingLoaded = false;
  const isExecutiveView = (viewName) => viewName === 'executive' || String(viewName || '').startsWith('executive-');
  const resolveViewName = (viewName) => {
    const target = viewName || 'home';
    if (!isMisAdmin && isExecutiveView(target)) {
      window.history.replaceState({}, document.title, 'index.html#home');
      return 'home';
    }
    if (!isMisAdmin && target === 'hrm') {
      window.history.replaceState({}, document.title, 'index.html#home');
      return 'home';
    }
    return target;
  };
  const showView = async (viewName) => {
    const target = resolveViewName(viewName);
    if (!target) return;

    document.querySelectorAll('.content-view').forEach((view) => {
      view.classList.toggle('show', view.id === `${target}-view`);
    });

    document.querySelectorAll('[data-view-link]').forEach((link) => {
      const active = link.dataset.viewLink === target;
      link.classList.toggle('active', active);
      if (active) {
        link.setAttribute('aria-current', 'page');
        const section = link.closest('.sidebar-section-links');
        const sectionButton = section?.previousElementSibling;
        section?.classList.add('show');
        sectionButton?.classList.add('expanded');
        sectionButton?.setAttribute('aria-expanded', 'true');
        const subsection = link.closest('.sidebar-subsection-links');
        const subsectionButton = subsection?.previousElementSibling;
        const dashboardContent = link.closest('.sidebar-dashboard-content');
        const dashboardButton = dashboardContent?.previousElementSibling;
        subsection?.classList.add('show');
        subsectionButton?.classList.add('expanded');
        subsectionButton?.setAttribute('aria-expanded', 'true');
        dashboardContent?.classList.add('show');
        dashboardButton?.classList.add('expanded');
        dashboardButton?.setAttribute('aria-expanded', 'true');
      } else {
        link.removeAttribute('aria-current');
      }
    });

    if (target === 'personal' && !personalLoaded) {
      personalLoaded = true;
      try {
        await ensureHomeModule('personal');
        if (typeof loadPersonalProfile === 'function') loadPersonalProfile(user);
      } catch (err) {
        console.error(err);
        personalLoaded = false;
      }
    }

    if (target === 'research' && !researchLoaded) {
      researchLoaded = true;
      try {
        await ensureHomeModule('research');
        if (typeof loadResearch === 'function') loadResearch();
      } catch (err) {
        console.error(err);
        researchLoaded = false;
      }
    }

    if (target === 'faculty-practice' && !facultyPracticeLoaded) {
      facultyPracticeLoaded = true;
      try {
        await ensureHomeModule('faculty-practice');
        if (typeof loadFacultyPractice === 'function') loadFacultyPractice();
      } catch (err) {
        console.error(err);
        facultyPracticeLoaded = false;
      }
    }

    if (target === 'training' && !trainingLoaded) {
      trainingLoaded = true;
      try {
        await ensureHomeModule('training');
        if (typeof loadTraining === 'function') loadTraining();
      } catch (err) {
        console.error(err);
        trainingLoaded = false;
      }
    }

  };

  document.querySelectorAll('[data-view-link]').forEach((link) => {
    link.addEventListener('click', (event) => {
      event.preventDefault();
      const viewName = link.dataset.viewLink || 'home';
      window.location.hash = viewName;
      showView(viewName);
      sidebar?.classList.remove('open');
      backdrop?.classList.remove('show');
    });
  });

  window.addEventListener('hashchange', () => {
    showView(window.location.hash.replace('#', '') || 'home');
  });

  const sidebar = document.getElementById('app-sidebar');
  const shell = document.getElementById('app-shell');
  const backdrop = document.getElementById('sidebar-backdrop');
  const toggleSidebar = () => {
    if (window.matchMedia('(min-width: 901px)').matches) {
      const collapsed = shell?.classList.toggle('sidebar-collapsed');
      document.getElementById('sidebar-toggle')?.setAttribute('aria-expanded', String(!collapsed));
      sidebar?.classList.remove('open');
      backdrop?.classList.remove('show');
      return;
    }
    const opened = sidebar?.classList.toggle('open');
    document.getElementById('sidebar-toggle')?.setAttribute('aria-expanded', String(Boolean(opened)));
    backdrop?.classList.toggle('show', Boolean(opened));
  };
  document.getElementById('sidebar-toggle')?.addEventListener('click', toggleSidebar);
  backdrop?.addEventListener('click', () => {
    sidebar?.classList.remove('open');
    document.getElementById('sidebar-toggle')?.setAttribute('aria-expanded', 'false');
    backdrop.classList.remove('show');
  });

  const initialView = window.location.hash.replace('#', '') || 'home';
  showView(initialView);
}
